insert into public.employees(id,organization_id,code,display_name,membership_id) values(md5('e21')::uuid,md5('o2')::uuid,'E1','Synthetic',md5('m21')::uuid);
insert into public.employees(id,organization_id,code,display_name,membership_id) values(md5('e22')::uuid,md5('o2')::uuid,'E2','Synthetic',md5('m22')::uuid);
insert into public.employees(id,organization_id,code,display_name,membership_id) values(md5('e23')::uuid,md5('o2')::uuid,'E3','Synthetic',md5('m23')::uuid);
insert into public.employees(id,organization_id,code,display_name) values(md5('e24')::uuid,md5('o2')::uuid,'NOEMAIL','No email');
set constraints all immediate;
select ok(((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.organizations'::regclass)),'FORCE RLS organizations');
select ok(((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.memberships'::regclass)),'FORCE RLS memberships');
select ok(((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.employees'::regclass)),'FORCE RLS employees');
select ok(((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.audit_log'::regclass)),'FORCE RLS audit_log');
select ok(((select not rolcanlogin and not rolsuper and not rolbypassrls and not rolcreaterole from pg_roles where rolname='fichaje_reader')),'minimal role fichaje_reader');
select ok((not pg_has_role('authenticated','fichaje_reader','MEMBER')),'no role inheritance fichaje_reader');
select ok(((select not rolcanlogin and not rolsuper and not rolbypassrls and not rolcreaterole from pg_roles where rolname='fichaje_writer')),'minimal role fichaje_writer');
select ok((not pg_has_role('authenticated','fichaje_writer','MEMBER')),'no role inheritance fichaje_writer');
select ok((not has_schema_privilege('authenticated','private','USAGE')),'private schema hidden');
select ok((not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prosecdef and not coalesce(p.proconfig @> array['search_path=""'],false))),'definer search paths empty');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',md5('u11')::uuid,'role','authenticated')::text,true);
set local role authenticated;
select ok(((select count(*) from public.organizations)=1),'TEN-01 1 OWNER own organization');
select ok(((select count(*) from public.memberships)=3),'TEN-01 1 OWNER memberships');
select ok(((select count(*) from public.employees)=4),'TEN-01 1 OWNER employees');
select ok((not exists(select 1 from public.employees where organization_id=md5('o2')::uuid)),'TEN-03 1 OWNER foreign UUID');
select ok((not exists(select 1 from public.employees e join public.memberships m on e.membership_id=m.id where m.organization_id=md5('o2')::uuid)),'TEN-05 1 OWNER join');
select throws_ok($test$select public.manage_employee(md5('o2')::uuid,gen_random_uuid(),md5('evil')::uuid,0,'X','X',null,true)$test$,'42501','FORBIDDEN','TEN-02 1 OWNER cross RPC');
select throws_ok($test$update public.memberships set role='OWNER'$test$,'42501',NULL,'ROLE-01 1 OWNER direct write denied');
select throws_ok($test$truncate public.employees$test$,'42501',NULL,'1 OWNER truncate denied');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',md5('u12')::uuid,'role','authenticated')::text,true);
set local role authenticated;
select ok(((select count(*) from public.organizations)=1),'TEN-01 1 ADMIN own organization');
select ok(((select count(*) from public.memberships)=3),'TEN-01 1 ADMIN memberships');
select ok(((select count(*) from public.employees)=4),'TEN-01 1 ADMIN employees');
