select ok((not exists(select 1 from public.employees e join public.memberships m on e.membership_id=m.id where m.organization_id=md5('o2')::uuid)),'TEN-05 1 ADMIN join');
select throws_ok($test$select public.manage_employee(md5('o2')::uuid,gen_random_uuid(),md5('evil')::uuid,0,'X','X',null,true)$test$,'42501','FORBIDDEN','TEN-02 1 ADMIN cross RPC');
select throws_ok($test$update public.memberships set role='OWNER'$test$,'42501',NULL,'ROLE-01 1 ADMIN direct write denied');
select throws_ok($test$truncate public.employees$test$,'42501',NULL,'1 ADMIN truncate denied');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',md5('u13')::uuid,'role','authenticated')::text,true);
