select ok(((select count(*) from public.memberships)=3),'TEN-01 2 OWNER memberships');
select ok(((select count(*) from public.employees)=4),'TEN-01 2 OWNER employees');
select ok((not exists(select 1 from public.employees where organization_id=md5('o1')::uuid)),'TEN-03 2 OWNER foreign UUID');
select ok((not exists(select 1 from public.employees e join public.memberships m on e.membership_id=m.id where m.organization_id=md5('o1')::uuid)),'TEN-05 2 OWNER join');
select throws_ok($test$select public.manage_employee(md5('o1')::uuid,gen_random_uuid(),md5('evil')::uuid,0,'X','X',null,true)$test$,'42501','FORBIDDEN','TEN-02 2 OWNER cross RPC');
select throws_ok($test$update public.memberships set role='OWNER'$test$,'42501',NULL,'ROLE-01 2 OWNER direct write denied');
select throws_ok($test$truncate public.employees$test$,'42501',NULL,'2 OWNER truncate denied');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',md5('u22')::uuid,'role','authenticated')::text,true);
set local role authenticated;
select ok(((select count(*) from public.organizations)=1),'TEN-01 2 ADMIN own organization');
select ok(((select count(*) from public.memberships)=3),'TEN-01 2 ADMIN memberships');
select ok(((select count(*) from public.employees)=4),'TEN-01 2 ADMIN employees');
