select ok((not exists(select 1 from public.employees e join public.memberships m on e.membership_id=m.id where m.organization_id=md5('o1')::uuid)),'TEN-05 2 EMPLOYEE join');
select throws_ok($test$select public.manage_employee(md5('o1')::uuid,gen_random_uuid(),md5('evil')::uuid,0,'X','X',null,true)$test$,'42501','FORBIDDEN','TEN-02 2 EMPLOYEE cross RPC');
select throws_ok($test$update public.memberships set role='OWNER'$test$,'42501',NULL,'ROLE-01 2 EMPLOYEE direct write denied');
